const $=id=>document.getElementById(id);
const storage={get(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}};
let place=storage.get('atmos-place',{name:'London',country:'United Kingdom',latitude:51.5085,longitude:-.1257,timezone:'Europe/London'}),data=null,unit=storage.get('atmos-unit','c'),twelve=storage.get('atmos-clock',false),weatherRequest=0,searchRequest=0;
let zone=place.timezone||'Europe/London';try{new Intl.DateTimeFormat('en',{timeZone:zone})}catch{zone='Europe/London'}
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function condition(code,day=true){if(code===0)return[day?'Clear skies':'Clear night',day?'☀':'☾'];if(code<3)return['Partly cloudy',day?'🌤':'☾'];if(code===3)return['Overcast','☁'];if(code<49)return['Misty','≋'];if(code<58)return['Drizzle','☂'];if(code<68)return['Rain','☂'];if(code<78)return['Snow','❄'];if(code<83)return['Rain showers','☂'];if(code<87)return['Snow showers','❄'];return['Thunderstorms','ϟ']}
const temp=n=>n==null?'—':Math.round(unit==='f'?n*9/5+32:n)+'°';
function time(value,opts={}){return new Intl.DateTimeFormat('en-GB',{timeZone:zone,...opts}).format(new Date(value*1000))}
function clock(){const now=new Date();const parts=new Intl.DateTimeFormat('en-GB',{timeZone:zone,hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:twelve}).formatToParts(now);const p=t=>parts.find(x=>x.type===t)?.value||'';$('clock').textContent=p('hour')+':'+p('minute');$('seconds').textContent=p('second');$('period').textContent=p('dayPeriod').toUpperCase();$('date').textContent=new Intl.DateTimeFormat('en-GB',{timeZone:zone,weekday:'long',day:'numeric',month:'long'}).format(now);$('timezone').textContent=zone.replaceAll('_',' ').replaceAll('/',' / ');$('clockFormat').textContent=`Switch to ${twelve?'24':'12'}-hour ↗`;const h=Number(new Intl.DateTimeFormat('en-GB',{timeZone:zone,hour:'numeric',hourCycle:'h23'}).format(now));$('greeting').textContent=h<12?'A FRESH START. A NEW PERSPECTIVE.':h<18?'MAKE TIME FOR THE MOMENT':'SLOW DOWN. LOOK UP.'}
function render(){ $('celsius').classList.toggle('active',unit==='c');$('fahrenheit').classList.toggle('active',unit==='f');$('celsius').setAttribute('aria-pressed',unit==='c');$('fahrenheit').setAttribute('aria-pressed',unit==='f');if(!data)return;const c=data.current,d=data.daily,h=data.hourly,desc=condition(c.weather_code,c.is_day);$('city').textContent=place.name;$('region').textContent=[place.admin1,place.country].filter(Boolean).join(', ');$('temperature').textContent=temp(c.temperature_2m);$('condition').textContent=desc[0];$('weatherIcon').textContent=desc[1];$('feels').textContent=`Feels like ${temp(c.apparent_temperature)} · High ${temp(d.temperature_2m_max[0])} / Low ${temp(d.temperature_2m_min[0])}`;$('wind').textContent=Math.round(c.wind_speed_10m)+' km/h';$('windDirection').textContent=['N','NE','E','SE','S','SW','W','NW'][Math.round(c.wind_direction_10m/45)%8]+' · wind direction';$('humidity').textContent=c.relative_humidity_2m+'%';let start=h.time.findIndex(t=>t>=Date.now()/1000);if(start<0)start=0;$('rain').textContent=(h.precipitation_probability[start]??0)+'%';$('sunset').textContent=time(d.sunset[0],{hour:'2-digit',minute:'2-digit'});$('sunrise').textContent='Sunrise '+time(d.sunrise[0],{hour:'2-digit',minute:'2-digit'});document.body.className=(c.is_day?'':'night ')+(c.weather_code>=51?'rainy':c.weather_code<3?'clear':'cloudy');$('hourly').innerHTML=h.time.slice(start,start+24).map((t,i)=>{const j=start+i;return `<article class="hour"><span>${time(t,{hour:'2-digit',minute:'2-digit'})}</span><b aria-label="${condition(h.weather_code[j],h.is_day[j])[0]}">${condition(h.weather_code[j],h.is_day[j])[1]}</b><strong>${temp(h.temperature_2m[j])}</strong><small>☂ ${h.precipitation_probability[j]??0}%</small></article>`}).join('');$('daily').innerHTML=d.time.map((t,i)=>`<article class="day"><span>${i===0?'Today':time(t,{weekday:'short'})}</span><b aria-label="${condition(d.weather_code[i])[0]}">${condition(d.weather_code[i])[1]}</b><strong>${temp(d.temperature_2m_max[i])}</strong><em>${temp(d.temperature_2m_min[i])}</em><small>☂ ${d.precipitation_probability_max[i]??0}%</small></article>`).join('');$('updated').textContent='Weather as of '+time(c.time,{hour:'2-digit',minute:'2-digit'})+' · auto-refresh 5 min';clock()}
async function json(url){const r=await fetch(url,{signal:AbortSignal.timeout(18000)});if(!r.ok)throw new Error('Weather service unavailable');return r.json()}
async function load(next=place){const id=++weatherRequest;$('status').textContent='Updating the forecast…';$('refresh').disabled=true;try{const params=new URLSearchParams({latitude:next.latitude,longitude:next.longitude,current:'temperature_2m,relative_humidity_2m,apparent_temperature,is_day,weather_code,wind_speed_10m,wind_direction_10m',hourly:'temperature_2m,precipitation_probability,weather_code,is_day',daily:'weather_code,temperature_2m_max,temperature_2m_min,sunrise,sunset,precipitation_probability_max',timezone:'auto',timeformat:'unixtime',forecast_days:'7'});const result=await json('https://api.open-meteo.com/v1/forecast?'+params);if(id!==weatherRequest)return;if(!result.current||!result.daily||!result.hourly)throw new Error('Incomplete forecast');data=result;zone=result.timezone;place={...next,timezone:zone};storage.set('atmos-place',place);render();$('status').textContent='Live clock · latest available weather';}catch(e){if(id===weatherRequest)$('status').textContent=data?'Could not refresh. Previous weather remains visible. Try Refresh weather.':'Weather couldn’t load. Check your connection and try Refresh weather.'}finally{if(id===weatherRequest)$('refresh').disabled=false}}
$('search').addEventListener('submit',async e=>{e.preventDefault();const q=$('query').value.trim();if(q.length<2)return;const id=++searchRequest;$('results').hidden=false;$('results').innerHTML='<p>Searching the world…</p>';try{const found=await json('https://geocoding-api.open-meteo.com/v1/search?name='+encodeURIComponent(q)+'&count=6&language=en&format=json');if(id!==searchRequest)return;$('results').innerHTML='';if(!found.results?.length){$('results').innerHTML='<p>No places found. Try a nearby city.</p>';return}found.results.forEach(p=>{const b=document.createElement('button');b.type='button';b.textContent=[p.name,p.admin1,p.country].filter(Boolean).join(', ');b.onclick=()=>{$('results').hidden=true;$('query').value='';load(p)};$('results').appendChild(b)})}catch{if(id===searchRequest)$('results').innerHTML='<p>Search unavailable. Please try again.</p>'}});
document.addEventListener('click',e=>{if(!e.target.closest('.toolbar'))$('results').hidden=true});document.addEventListener('keydown',e=>{if(e.key==='Escape')$('results').hidden=true});
$('locate').onclick=()=>{if(!navigator.geolocation){$('status').textContent='Location is unavailable in this browser. Search for a city instead.';return}$('status').textContent='Waiting for your location…';navigator.geolocation.getCurrentPosition(p=>load({name:'Your location',country:`${p.coords.latitude.toFixed(2)}°, ${p.coords.longitude.toFixed(2)}°`,latitude:p.coords.latitude,longitude:p.coords.longitude}),()=>{$('status').textContent='Location access unavailable. Search for your city above.'},{timeout:12000,maximumAge:300000})};
$('celsius').onclick=()=>{unit='c';storage.set('atmos-unit',unit);render()};$('fahrenheit').onclick=()=>{unit='f';storage.set('atmos-unit',unit);render()};$('clockFormat').onclick=()=>{twelve=!twelve;storage.set('atmos-clock',twelve);clock()};$('refresh').onclick=()=>load();window.addEventListener('online',()=>load());document.addEventListener('visibilitychange',()=>{if(!document.hidden){clock();if(data&&Date.now()/1000-data.current.time>300)load()}});$('city').textContent=place.name;$('region').textContent=place.country||'';clock();render();setInterval(clock,1000);setInterval(()=>load(),300000);load();
